"use strict";(self.webpackChunk=self.webpackChunk||[]).push([[3738],{4693:(e,a,n)=>{n.r(a),n.d(a,{data:()=>t});const t={key:"v-6452a368",path:"/fr_FR/troubleshooting.html",title:"Problèmes et dépannage",lang:"fr-FR",frontmatter:{},excerpt:"",headers:[{level:2,title:"Unlaunch",slug:"unlaunch",children:[{level:3,title:"Unlaunch plante à MISMATCH IN FAT COPIES ?",slug:"unlaunch-plante-a-mismatch-in-fat-copies",children:[]},{level:3,title:'Il n\'y a pas de son ou de chargement de démarrage lors du lancement de "LAUNCHER" en utilisant Unlaunch',slug:"il-n-y-a-pas-de-son-ou-de-chargement-de-demarrage-lors-du-lancement-de-launcher-en-utilisant-unlaunch",children:[]}]}],filePathRelative:"fr_FR/troubleshooting.md",git:{updatedTime:1634872835e3,contributors:[{name:"Pk11",email:"epicpkmn11@outlook.com",commits:1}]}}},6450:(e,a,n)=>{n.r(a),n.d(a,{default:()=>l});const t=(0,n(6252).uE)('<h1 id="problemes-et-depannage" tabindex="-1"><a class="header-anchor" href="#problemes-et-depannage" aria-hidden="true">#</a> Problèmes et dépannage</h1><h2 id="unlaunch" tabindex="-1"><a class="header-anchor" href="#unlaunch" aria-hidden="true">#</a> Unlaunch</h2><h3 id="unlaunch-plante-a-mismatch-in-fat-copies" tabindex="-1"><a class="header-anchor" href="#unlaunch-plante-a-mismatch-in-fat-copies" aria-hidden="true">#</a> Unlaunch plante à <code>MISMATCH IN FAT COPIES</code> ?</h3><p>twlnf a un bug critique où il ne met pas correctement à jour la NAND entière après l&#39;avoir modifié, ce qui fait que certains homebrews (comme l&#39;installateur d&#39;Unlaunch) montrent une erreur.</p><p>Bien qu&#39;il soit possible d&#39;y remédier, la méthode pour le faire n&#39;est pas fixée et varie largement d&#39;un système à l&#39;autre. Une méthode consiste à supprimer tous les titres DSiWare installé via twlnf dans le passé, mais il a également été signalé que leur déplacement à <em>tous</em> sur la carte SD et de nouveau sur le système peut aider dans certains cas.</p><p>Si vous avez rétrogradé le système dans le passé, la mise à jour vers la version 1.4.5 (ou 1.4.6 si votre région DS est chinoise ou coréenne) peut également résoudre ce problème.</p><h3 id="il-n-y-a-pas-de-son-ou-de-chargement-de-demarrage-lors-du-lancement-de-launcher-en-utilisant-unlaunch" tabindex="-1"><a class="header-anchor" href="#il-n-y-a-pas-de-son-ou-de-chargement-de-demarrage-lors-du-lancement-de-launcher-en-utilisant-unlaunch" aria-hidden="true">#</a> Il n&#39;y a pas de son ou de chargement de démarrage lors du lancement de &quot;LAUNCHER&quot; en utilisant Unlaunch</h3><p>Le développeur de Unlaunch (nocash) a intentionnellement désactivé le fond sonore et le chargement de démarrage par défaut. Vous pouvez récupérer ces effets en <a href="/installing-unlaunch">réinstallant Unlaunch</a> avec TWiLight Menu++.</p>',8),r={},l=(0,n(3744).Z)(r,[["render",function(e,a){return t}]])},3744:(e,a)=>{a.Z=(e,a)=>{for(const[n,t]of a)e[n]=t;return e}}}]);